<script module lang="ts">
/**
 * Block of code, such as an install command or config sample (`design/components/code-block.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/code-block.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, type Snippet } from 'svelte'

import { SlotText, joinSlot, watchEffect } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/code-block.module.css'
import Button from '../controls/Button.svelte'

export interface CodeBlockProps {
  /**
   * The code, rendered verbatim including whitespace.
   */
  children: Snippet
  /**
   * Draws the copy control, the block's only control.
   */
  copyable?: boolean
  /**
   * The copy control's accessible name, default `'Copy'`; apps pass a localized one.
   */
  copyLabel?: string
  /**
   * The accessible name when the block overflows and becomes a scroll region; defaults to `'Code
   * block'`, and apps pass a localized one.
   */
  label?: string
}
</script>

<script lang="ts">
let {
  children,
  copyable = false,
  copyLabel = 'Copy',
  label: labelOwn = 'Code block',
}: CodeBlockProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
let overflowing = $state(false)
let copied = $state(false)
let copies = $state(0)
let block = $state<HTMLElement | null>(null)
const copy = $derived(
  () =>
    void navigator.clipboard.writeText(childrenText.current).then(
      () => {
        copied = true
        copies += 1
      },
      () => undefined,
    ),
)
const childrenText = new SlotText(() => children)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const run = () => {
    overflowing = block !== null && block.scrollWidth > block.clientWidth
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [block]) if (element) resize?.observe(element)
  const mutation = typeof MutationObserver === 'undefined' ? undefined : new MutationObserver(run)
  for (const element of [block])
    if (element) mutation?.observe(element, { childList: true, characterData: true, subtree: true })
  release1 = () => {
    resize?.disconnect()
    mutation?.disconnect()
  }
  run()
}
watchEffect(effect1, { watch: () => copyable })
onDestroy(() => release1?.())
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const timer = setTimeout(() => {
    copied = false
  }, 2000)
  release2 = () => clearTimeout(timer)
}
watchEffect(effect2, { watch: () => copies, mount: false })
onDestroy(() => release2?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#if copyable
    }<div class={styles.copyable} data-state={(copied) ? 'copied' : undefined}
      ><pre
        bind:this={block}
        class={styles.block}
        data-overflowing={(overflowing) ? '' : undefined}
        data-copyable={(copyable) ? '' : undefined}
        tabindex={((overflowing) ? 0 : undefined) as never}
        role={(overflowing) ? 'region' : undefined}
        aria-label={(overflowing) ? label : undefined}
        data-member="code-block"
        ><code>{@render children?.()}</code
      ></pre
      ><div class={styles.control}
        ><Button
          variant="ghost"
          tone="neutral"
          size="sm"
          iconOnly={true}
          icon={copied ? 'confirm' : 'copy'}
          label={copyLabel}
          onClick={() => { copy() }}
      /></div
      ><span class={styles.reader} aria-live="polite">{copied ? 'Copied' : ''}</span
    ></div
  >{:else
    }<pre
      bind:this={block}
      class={styles.block}
      data-overflowing={(overflowing) ? '' : undefined}
      data-copyable={(copyable) ? '' : undefined}
      tabindex={((overflowing) ? 0 : undefined) as never}
      role={(overflowing) ? 'region' : undefined}
      aria-label={(overflowing) ? label : undefined}
      data-member="code-block"
      ><code>{@render children?.()}</code
    ></pre
  >{/if
}{/if
}{@render joined.end?.()}
